(() => {
const root=document.querySelector('[data-bag-library]');if(!root)return;
const lang=document.documentElement.lang.startsWith('zh')?'zh':document.documentElement.lang==='vi'?'vi':'en';const tr=(vi,en,zh)=>({vi,en,zh})[lang];
const normalize=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[đĐ]/g,'d').toLowerCase().trim();
const cards=[...root.querySelectorAll('.bag-card')],input=document.querySelector('#bag-query'),filters=[...root.querySelectorAll('[data-bag-filter]')],allowed=new Set(filters.map(b=>b.dataset.bagFilter)),products=new Map(window.HOTPRINT_PRODUCTS.map(p=>[p.id,p]));
const hay=new Map(cards.map(c=>{const p=products.get(c.dataset.model);return[c,normalize([p.id,p.vi,p.en,p.zh].join(' '))]}));
const read=()=>{const p=new URL(location.href).searchParams;return{q:(p.get('q')||'').slice(0,100),use:allowed.has(p.get('use'))?p.get('use'):'all'}};let state=read();
function links(){document.querySelectorAll('[data-lang]').forEach(a=>{const u=new URL(a.href);u.search=location.search;u.hash=location.hash;a.href=u.href})}
function render(){input.value=state.q;let n=0;const terms=normalize(state.q).split(/\s+/).filter(Boolean);cards.forEach(c=>{c.hidden=(state.use!=='all'&&c.dataset.use!==state.use)||!terms.every(t=>hay.get(c).includes(t));if(!c.hidden)n++});filters.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.bagFilter===state.use)));document.querySelector('#fold-result-count').textContent=n+' '+tr('mẫu túi','paper bags','款纸袋');document.querySelector('#bag-empty').hidden=n>0;links()}
function update(push){const u=new URL(location.href);state.q?u.searchParams.set('q',state.q):u.searchParams.delete('q');state.use!=='all'?u.searchParams.set('use',state.use):u.searchParams.delete('use');history[push?'pushState':'replaceState'](null,'',u);render()}
filters.forEach(b=>b.onclick=()=>{state.use=b.dataset.bagFilter;update(true)});input.maxLength=100;input.addEventListener('input',()=>{state.q=input.value.slice(0,100);update(false)});root.querySelector('[data-bag-reset]').onclick=()=>{state={q:'',use:'all'};update(true);input.focus()};window.addEventListener('popstate',()=>{state=read();render()});window.addEventListener('hashchange',links);render();
const ids=['HP7073','032A5355','032A5311','032A5357'];let slide=0;
function show(i){slide=(i+ids.length)%ids.length;document.querySelectorAll('[data-bag-panel]').forEach(p=>p.hidden=Number(p.dataset.bagPanel)!==slide);document.querySelectorAll('[data-bag-slide]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.bagSlide)===slide)));const p=products.get(ids[slide]),name=p[lang]||(lang==='zh'?HOTPRINT_I18N.translate(p.en):p.en);document.querySelector('#bag-slide-name').textContent=name;document.querySelector('#bag-slide-open').dataset.foldDetail=ids[slide];document.querySelector('#bag-slide-status').textContent=`${slide+1} / ${ids.length}: ${name}`;}
document.querySelector('#bag-slide-prev').onclick=()=>show(slide-1);document.querySelector('#bag-slide-next').onclick=()=>show(slide+1);document.querySelectorAll('[data-bag-slide]').forEach(b=>b.onclick=()=>show(Number(b.dataset.bagSlide)));show(0);
})();
